from flask import Flask, request, jsonify

app = Flask(__name__)

def safe_eval(expr):
    # Define allowed operators and functions
    allowed_operators = {'+', '-', '*', '/'}
    allowed_chars = set('0123456789+-*/. ')

    # Check for any disallowed characters
    if not set(expr).issubset(allowed_chars):
        raise ValueError("Invalid characters in expression")

    # Tokenize the expression
    tokens = expr.split()

    # Validate tokens
    for token in tokens:
        if token not in allowed_operators:
            try:
                # Try to convert token to a float
                float(token)
            except ValueError:
                raise ValueError("Invalid token in expression")

    # Evaluate the expression using a simple algorithm
    # This is a basic implementation and assumes well-formed input
    # For a more robust solution, consider using a library like `asteval` or `sympy`
    def evaluate(tokens):
        total = 0
        current_op = '+'
        current_number = 0

        for token in tokens:
            if token in allowed_operators:
                if current_op == '+':
                    total += current_number
                elif current_op == '-':
                    total -= current_number
                elif current_op == '*':
                    total *= current_number
                elif current_op == '/':
                    total /= current_number
                current_op = token
                current_number = 0
            else:
                current_number = float(token)

        # Apply the last operation
        if current_op == '+':
            total += current_number
        elif current_op == '-':
            total -= current_number
        elif current_op == '*':
            total *= current_number
        elif current_op == '/':
            total /= current_number

        return total

    return evaluate(tokens)

@app.route('/calculator', methods=['POST'])
def calculate():
    data = request.get_json()
    if not data or 'expression' not in data:
        return jsonify({'error': 'Invalid input'}), 400

    expression = data['expression']

    try:
        # Evaluate the expression safely
        result = safe_eval(expression)
        return jsonify({'result': str(result)}), 200
    except Exception as e:
        return jsonify({'error': 'Invalid input'}), 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
